fn model_xor1(b_a: V, b_b: V) -> V {
    (if V::Bool(b_a.clone() == b_b.clone()).truthy() { V::Nat(0u64) } else { V::Nat(1u64) })
}

fn model_xor2(b_a: V, b_b: V) -> V {
    (if V::compare(&b_a.clone(), &V::Nat(2u64), ">=").truthy() { (if V::compare(&b_b.clone(), &V::Nat(2u64), ">=").truthy() { model_xor1(V::arith(&b_a.clone(), &V::Nat(2u64), '-'), V::arith(&b_b.clone(), &V::Nat(2u64), '-')) } else { V::arith(&V::Nat(2u64), &model_xor1(V::arith(&b_a.clone(), &V::Nat(2u64), '-'), b_b.clone()), '+') }) } else { (if V::compare(&b_b.clone(), &V::Nat(2u64), ">=").truthy() { V::arith(&V::Nat(2u64), &model_xor1(b_a.clone(), V::arith(&b_b.clone(), &V::Nat(2u64), '-')), '+') } else { model_xor1(b_a.clone(), b_b.clone()) }) })
}

