fn op_add(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of add fits u8");
    let p1 = u8::try_from(args[1].u64v()).expect("argument 1 of add fits u8");
    let fault = fault_for("add", fault);
    let r: u8 = match fault {
            Fault::OrForXor => p0 | p1,
            Fault::WrappingSub => p0.wrapping_sub(p1),
            _ => add(p0, p1),
        };
    V::Nat(u64::from(r))
}

fn op_subtract(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of subtract fits u8");
    let p1 = u8::try_from(args[1].u64v()).expect("argument 1 of subtract fits u8");
    let fault = fault_for("subtract", fault);
    let r: u8 = match fault {
            Fault::OrForXor => p0 | p1,
            Fault::WrappingSub => p0.wrapping_sub(p1),
            _ => subtract(p0, p1),
        };
    V::Nat(u64::from(r))
}

fn op_multiply(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of multiply fits u8");
    let p1 = u8::try_from(args[1].u64v()).expect("argument 1 of multiply fits u8");
    let fault = fault_for("multiply", fault);
    let r: u8 = match fault {
            Fault::MulAsAdd => p0 ^ p1,
            Fault::AltPoly => gf256::Field::new(0x11B).multiply(p0, p1),
            _ => multiply(p0, p1),
        };
        let r: u8 = match fault {
            Fault::GeneratorShift => if r == 0 { r } else { gf256::multiply(r, 2) },
            _ => r,
        };
    V::Nat(u64::from(r))
}

fn op_divide(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of divide fits u8");
    let p1 = u8::try_from(args[1].u64v()).expect("argument 1 of divide fits u8");
    let fault = fault_for("divide", fault);
    match contained(|| {
        let r: u8 = match fault {
            Fault::AltPoly => gf256::Field::new(0x11B).divide(p0, p1),
            _ => divide(p0, p1),
        };
        let r: u8 = match fault {
            Fault::GeneratorShift => if r == 0 { r } else { gf256::multiply(r, 2) },
            _ => r,
        };
        r
    }) {
        Some(r) => V::Ok(Box::new(V::Nat(u64::from(r)))),
        None if fault == Fault::MissingError => V::Ok(Box::new(V::Nat(0))),
        None => V::Err("DIVIDE_BY_ZERO".into()),
    }
}

fn op_inverse(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of inverse fits u8");
    let fault = fault_for("inverse", fault);
    match contained(|| {
        let r: u8 = match fault {
            Fault::AltPoly => gf256::Field::new(0x11B).inverse(p0),
            _ => inverse(p0),
        };
        let r: u8 = match fault {
            Fault::GeneratorShift => if r == 0 { r } else { gf256::multiply(r, 2) },
            _ => r,
        };
        r
    }) {
        Some(r) => V::Ok(Box::new(V::Nat(u64::from(r)))),
        None if fault == Fault::MissingError => V::Ok(Box::new(V::Nat(0))),
        None => V::Err("ZERO_HAS_NO_INVERSE".into()),
    }
}

fn op_power(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].u64v()).expect("argument 0 of power fits u8");
    let p1 = u32::try_from(args[1].u64v()).expect("argument 1 of power fits u32");
    let fault = fault_for("power", fault);
    let p1 = if fault == Fault::ExpMod256 { let p = p1; p % 256 } else { p1 };
    let r: u8 = match fault {
            Fault::AltPoly => gf256::Field::new(0x11B).power(p0, p1),
            _ => power(p0, p1),
        };
        let r: u8 = match fault {
            Fault::GeneratorShift => if r == 0 { r } else { gf256::multiply(r, 2) },
            _ => r,
        };
    V::Nat(u64::from(r))
}

